  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const notificationOptions = [
        {
          value: "email",
          label: "Email",
          description: "Receive updates in your inbox for easy reference and follow-up."
        },
        {
          value: "sms",
          label: "SMS",
          description: "Get quick text alerts for timely reminders while you're on the go."
        },
        {
          value: "push",
          label: "Push Notifications",
          description: "See instant app notifications for the fastest real-time updates."
        }
      ];

      const escapeHtml = (value) =>
        String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");

      function RadioOption(option) {
        const id = "notification-" + option.value;

        return `
          <label class="radio-card">
            <input
              id="${escapeHtml(id)}"
              type="radio"
              name="notificationPreference"
              value="${escapeHtml(option.value)}"
              ${option.value === "email" ? "required" : ""}
              aria-describedby="notification-hint feedback-message"
            />
            <span class="radio-copy">
              <span class="radio-title">${escapeHtml(option.label)}</span>
              <span class="radio-description">${escapeHtml(option.description)}</span>
            </span>
          </label>
        `;
      }

      function FormSection() {
        return `
          <section class="card" aria-labelledby="preferences-title">
            <div class="card-header">
              <div class="card-title-group">
                <h2 class="card-title" id="preferences-title">Notification settings</h2>
                <p class="card-copy">Choose one delivery method so we can send alerts where they work best for you.</p>
              </div>
              <div class="required-badge" aria-label="Required field">Required *</div>
            </div>

            <form id="preferences-form" novalidate>
              <div class="form-field">
                <fieldset>
                  <legend>How do you prefer to receive notifications?</legend>
                  <p class="field-hint" id="notification-hint">Select exactly one option before submitting the form.</p>
                  <div class="radio-grid">
                    ${notificationOptions.map(RadioOption).join("")}
                  </div>
                </fieldset>
              </div>

              <p id="feedback-message" class="feedback feedback-error" aria-live="assertive" hidden></p>
              <p id="success-message" class="feedback feedback-success" aria-live="polite" hidden></p>

              <div class="actions">
                <button class="button" type="submit">Submit</button>
                <p class="footnote">Your selection can be updated later in account settings.</p>
              </div>
            </form>
          </section>
        `;
      }

      function App() {
        return `
          <main id="main-content" class="page-shell">
            <header class="hero">
              <p class="eyebrow">Product preferences</p>
              <h1>Stay in the loop your way</h1>
              <p class="intro">Set a notification preference with a simple, single-choice form designed for quick completion across desktop and mobile.</p>
            </header>
            ${FormSection()}
          </main>
        `;
      }

      const appRoot = document.getElementById("app");
      appRoot.innerHTML = App();

      const form = document.getElementById("preferences-form");
      const feedbackMessage = document.getElementById("feedback-message");
      const successMessage = document.getElementById("success-message");
      const radioInputs = Array.from(form.querySelectorAll('input[name="notificationPreference"]'));

      function setRadioInvalidState(isInvalid) {
        radioInputs.forEach((input) => {
          input.setAttribute("aria-invalid", String(isInvalid));
        });
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const selectedInput = radioInputs.find((input) => input.checked);

        feedbackMessage.hidden = true;
        feedbackMessage.textContent = "";
        successMessage.hidden = true;
        successMessage.textContent = "";

        if (!selectedInput) {
          setRadioInvalidState(true);
          feedbackMessage.textContent = "Please select one notification method before submitting.";
          feedbackMessage.hidden = false;
          radioInputs[0].focus();
          return;
        }

        setRadioInvalidState(false);
        const selectedOption = notificationOptions.find((option) => option.value === selectedInput.value);
        successMessage.textContent = "Preference saved: " + selectedOption.label + ".";
        successMessage.hidden = false;
      });

      radioInputs.forEach((input) => {
        input.addEventListener("change", () => {
          setRadioInvalidState(false);
          feedbackMessage.hidden = true;
          feedbackMessage.textContent = "";
        });
      });
    </script>
  </body>
</html>
