         const selectedOption = notificationOptions.find((option) => option.value === selectedInput.value);
         successMessage.textContent = "Preference saved: " + selectedOption.label + ".";
         successMessage.hidden = false;
       });

       radioInputs.forEach((input) => {
         input.addEventListener("change", () => {
           setRadioInvalidState(false);
           feedbackMessage.hidden = true;
           feedbackMessage.textContent = "";
         });
       });
